CREATE TEMP TABLE fork_visible_messages AS SELECT DISTINCT message.message_sequence FROM messages message JOIN item_catalog anchor ON anchor.jsonl_offset=message.jsonl_offset AND anchor.jsonl_length=message.jsonl_length JOIN fork_selected_items selected ON selected.item_id=anchor.item_id WHERE selected.visible_ordinal IS NOT NULL AND NOT EXISTS(SELECT 1 FROM item_catalog member LEFT JOIN fork_selected_items included ON included.item_id=member.item_id WHERE member.message_group_id=anchor.message_group_id AND included.visible_ordinal IS NULL)
